# Sources for the Rap Flow lessons (lessons/rap-flow.qmd, lessons/rap-flow-reading.qmd). Searched and read 2026-11-26.
# READ: Adams 2009 (full text, not the example images), Ohriner 2019 MTO (full text to 3.9, the rest by a fetch agent's summary),
# Komaniecki 2017 (full PDF text), Komaniecki 2021 (abstract and sections 1-2.2; the rest by summary), Waller 2016 (ch. 4 in full).
# ABSTRACT OR SECONDHAND ONLY (say so on the page): Duinker 2019 (abstract + reference list; paywalled), Condit-Schultz 2016
# (its numbers as Komaniecki [1.2] reports them; emusicology.org refuses automated reads), Krims 2000 (as Adams [6] quotes it),
# Duinker & Martin 2017 and Katz 2017 (search abstracts), Ohriner's book (publisher page and two reviews' openings), the rest titles.
L, R = "lessons/rap-flow.qmd", "lessons/rap-flow-reading.qmd"
B = [L, R]
SOURCES = [
    web('Adams, Kyle. "On the Metrical Techniques of Flow in Rap Music." *Music Theory Online*, vol. 15, no. 5, Oct. 2009, URL.',
        "https://www.mtosmt.org/issues/mto.09.15.5/mto.09.15.5.adams.php", B, who="student",
        note="Read in full (not the example images). Definition [1], [6]; the techniques [8]; Basketball vs Wu-Gambinos [3]-[4]; Blazing Arrow [10]-[15]; All Caps [16]-[25]; 100 Miles and Runnin' [26]-[32]; history [33]-[35]; grid fn. 2."),
    web('Ohriner, Mitchell. "Lyric, Rhythm, and Non-alignment in the Second Verse of Kendrick Lamar\'s \'Momma\'." *Music Theory Online*, vol. 25, no. 1, Mar. 2019, URL.',
        "https://www.mtosmt.org/ojs/index.php/mto/article/view/658/64", B, who="student",
        note="Read to [3.9]. The 16-position grid in rap teaching [1.3]-[1.4]; speech-rhythmic vs music-rhythmic [1.5], [2.1]-[2.5]; behind the beat [3.3]-[3.6]."),
    web('Komaniecki, Robert. "Analyzing Collaborative Flow in Rap Music." *Music Theory Online*, vol. 23, no. 4, Dec. 2017, URL.',
        "https://mtosmt.org/issues/mto.17.23.4/mto.17.23.4.komaniecki.pdf", B, who="student",
        note="Read in full. Groups in the 1980s and early 90s, solo artists with guests later [0.4]; Condit-Schultz's norms quoted [1.2]; unified flow in early groups section 2."),
    web('Komaniecki, Robert. "Vocal Pitch in Rap Flow." *Intégral*, vol. 34, 2021, pp. 25–45, URL.',
        "https://theory.esm.rochester.edu/integral/?p=5664", B, who="teacher",
        note="Abstract and sections 1-2.2 read; five pitch techniques from rhyme strengthening to sung verses."),
    web('Waller, Adam. *Rhythm and Flow in Hip-Hop Music: A Corpus Study*. 2016. University of Rochester, Eastman School of Music, PhD dissertation. URL.',
        "https://urresearch.rochester.edu/institutionalPublicationPublicView.action?institutionalItemId=31805", B, who="teacher",
        note="Chapter 4 read: 45 verses 1979-2009 from the Anthology of Rap (Fig. 4.1, p. 110); complexity rises to about 2000, then falls and spreads out (pp. 127-130)."),
    web('Duinker, Ben. "Good Things Come in Threes: Triplet Flow in Recent Hip-Hop Music." *Popular Music*, vol. 38, no. 3, 2019, pp. 423–456, URL.',
        "https://doi.org/10.1017/S026114301900028X", B, who="student",
        note="Abstract and reference list only (paywalled): mixed, phrasal and total triplet flow; late-1980s / early-1990s blueprint; a 50-song mini-corpus."),
    web('Condit-Schultz, Nathaniel. "MCFlow: A Digital Corpus of Rap Transcriptions." *Empirical Musicology Review*, vol. 11, no. 2, 2016, URL.',
        "https://emusicology.org/index.php/EMR/article/view/4961", B, who="teacher",
        note="Not read (the site refuses automated reads). Its numbers here are as Komaniecki 2017 [1.2] reports them: 124 Billboard tracks 1980-2015, about 4.5 syllables a second, about a quarter of stressed syllables rhymed, rhymes most often on beat 4."),
    book("Krims, Adam. *Rap Music and the Poetics of Identity*. Cambridge UP, 2000.", B, who="teacher",
         note="Not read; cited as Adams 2009 [6] and Waller 2016 (p. 111) quote it: sung, percussion-effusive and speech-effusive flow; old school to new school."),
    web("Ohriner, Mitchell. *Flow: The Rhythmic Voice in Rap Music*. Oxford UP, 2019. Oxford Studies in Music Theory. URL.",
        "https://global.oup.com/academic/product/flow-9780190670412", [R], who="teacher",
        note="Not read. About 200 verses by anglophone MCs (Tatar's review in the Journal of Music Theory 66.2, 2022, as a search summary gave it)."),
    web('de Lacey, Alex. Review of *Flow: The Rhythmic Voice in Rap Music*, by Mitchell Ohriner. *Journal of the Society for Musicology in Ireland*, vol. 15, 2020, pp. 31–35, URL.',
        "https://jsmi.musicologyireland.ie/index.php/journal/article/download/187/206/737", [R], who="teacher", note="Found, not read beyond a search summary."),
    web('Burkhart, Benjamin. Review of *Flow: The Rhythmic Voice in Rap Music*, by Mitchell Ohriner. *IASPM Journal*, vol. 11, no. 2, 2021, URL.',
        "https://iaspmjournal.net/index.php/IASPM_Journal/article/view/1085", [R], who="teacher", note="Found, not read."),
    web('Duinker, Ben, and Denis Martin. "In Search of the Golden Age Hip-Hop Sound (1986–1996)." *Empirical Musicology Review*, vol. 12, no. 1–2, 2017, pp. 80–100, URL.',
        "https://doi.org/10.18061/emr.v12i1-2.5410", [R], who="teacher", note="Abstract only: 100 tracks, eight parameters; tempo slowly falls."),
    book('Katz, Jonah. "Style and Flow: A Commentary on Duinker & Martin." *Empirical Musicology Review*, vol. 12, no. 1–2, 2017, pp. 101–108.', [R], who="teacher",
         note="Not read; from a search summary."),
    book("Duinker, Ben. *Diversification and Post-Regionalism in North American Hip-Hop Flow*. 2020. McGill University, PhD dissertation.", [R], who="teacher",
         note="Title only; the McGill link moved."),
    web('Mattessich, John. "This Flow Ain\'t Free: Generative Elements in Kendrick Lamar\'s *To Pimp a Butterfly*." *Music Theory Online*, vol. 25, no. 1, 2019, URL.',
        "https://www.mtosmt.org/ojs/index.php/mto/article/view/243/40", [R], who="teacher", note="Found, not read."),
    web('"Functions of Expressive Timing in Hip-Hop Flow." *Journal of Popular Music Studies*, vol. 34, no. 1, 2022, pp. 90–117, URL.',
        "https://online.ucpress.edu/jpms/article/34/1/90/120447/Functions-of-Expressive-Timing-in-Hip-Hop-Flow", [R], who="teacher",
        note="Found, not read (the page refused); author not seen."),
    book("Edwards, Paul. *How to Rap: The Art and Science of the Hip-Hop MC*. Chicago Review Press, 2009.", [R], who="student",
         note="Not read; Ohriner 2019 [1.3] cites it for a stressed syllable on each beat."),
    book("Connor, Martin E. *The Musical Artistry of Rap*. McFarland, 2018.", [R], who="student", note="Not read; from memory, unverified."),
    web('Caswell, Estelle. "How the Triplet Flow Took Over Rap." *Vox*, 18 Sept. 2017, URL.',
        "https://www.vox.com/2017/9/18/16328330/migos-triplet-flow-rap", [R], who="student", note="A video; cited by Duinker 2019. Not watched."),
]
